CREATE TABLE public.mygrowth_materials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), training_id uuid NOT NULL REFERENCES public.mygrowth_trainings(id), uploaded_by uuid NOT NULL REFERENCES auth.users(id), filename text NOT NULL CHECK(length(filename) BETWEEN 1 AND 200 AND filename !~ '[/\\]'), bytes bigint NOT NULL CHECK(bytes BETWEEN 1 AND 52428800), object_path text NOT NULL UNIQUE, ready boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.mygrowth_materials TO service_role;
REVOKE ALL ON public.mygrowth_materials FROM anon,authenticated;
ALTER TABLE public.mygrowth_materials ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.mygrowth_material_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), material_id uuid NOT NULL REFERENCES public.mygrowth_materials(id), user_id uuid NOT NULL REFERENCES auth.users(id), expires_at timestamptz NOT NULL DEFAULT (now()+interval '7 days'), created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.mygrowth_material_tickets TO service_role;
REVOKE ALL ON public.mygrowth_material_tickets FROM anon,authenticated;
ALTER TABLE public.mygrowth_material_tickets ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.mygrowth_material_scope(_training uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_mygrowth_reviewer() AND EXISTS(SELECT 1 FROM public.mygrowth_trainings t WHERE t.id=_training AND t.session_kind='education' AND (public.mygrowth_session_scope(t.id) OR EXISTS(SELECT 1 FROM public.mygrowth_training_targets x JOIN public.mygrowth_staff_registry s ON s.user_id=x.user_id JOIN public.profiles p ON p.user_id=s.user_id WHERE x.training_id=t.id AND x.user_id=auth.uid() AND x.attendance_status='attended' AND t.attendance_version>0 AND s.active AND x.tenant_id=t.tenant_id AND x.branch_id=t.branch_id AND s.tenant_id=t.tenant_id AND s.branch_id=t.branch_id AND p.tenant_id=s.tenant_id AND p.department_id=s.branch_id))) $$;
CREATE FUNCTION public.mygrowth_material_list(_training uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.mygrowth_material_scope(_training) THEN RAISE EXCEPTION '교육자료 조회 권한이 없습니다.' USING ERRCODE='42501'; END IF; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'filename',filename,'bytes',bytes,'created_at',created_at) ORDER BY created_at,id) FROM public.mygrowth_materials WHERE training_id=_training AND ready),'[]'::jsonb); END $$;
CREATE FUNCTION public.mygrowth_material_reserve(_training uuid,_filename text,_bytes bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result record; new_id uuid; BEGIN
IF NOT public.is_mygrowth_reviewer() OR NOT public.mygrowth_session_scope(_training) OR NOT EXISTS(SELECT 1 FROM public.mygrowth_trainings WHERE id=_training AND session_kind='education') THEN RAISE EXCEPTION '교육자료 등록 권한이 없습니다.' USING ERRCODE='42501'; END IF;
IF _filename IS NULL OR length(_filename) NOT BETWEEN 1 AND 200 OR _filename ~ '[/\\]' OR lower(_filename) !~ '\.(doc|docx|pdf|xls|xlsx|ppt|pptx)$' OR _bytes IS NULL OR _bytes NOT BETWEEN 1 AND 52428800 THEN RAISE EXCEPTION '워드·PDF·엑셀·PPT 파일과 50MB 이하 용량을 확인하십시오.' USING ERRCODE='22023'; END IF;
new_id=gen_random_uuid(); INSERT INTO public.mygrowth_materials(id,training_id,uploaded_by,filename,bytes,object_path) VALUES(new_id,_training,auth.uid(),_filename,_bytes,_training::text||'/'||new_id::text) RETURNING * INTO result;
RETURN jsonb_build_object('id',result.id,'path',result.object_path); END $$;
CREATE FUNCTION public.mygrowth_material_issue(_material uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF NOT EXISTS(SELECT 1 FROM public.mygrowth_materials WHERE id=_material AND ready AND public.mygrowth_material_scope(training_id)) THEN RAISE EXCEPTION '교육자료 내려받기 권한이 없습니다.' USING ERRCODE='42501'; END IF; INSERT INTO public.mygrowth_material_tickets(material_id,user_id) VALUES(_material,auth.uid()) RETURNING id INTO result; RETURN result; END $$;
CREATE FUNCTION public.mygrowth_material_redeem(_ticket uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN SELECT jsonb_build_object('path',m.object_path,'filename',m.filename,'bytes',m.bytes) INTO result FROM public.mygrowth_material_tickets k JOIN public.mygrowth_materials m ON m.id=k.material_id WHERE k.id=_ticket AND k.user_id=auth.uid() AND k.expires_at>now() AND m.ready AND public.mygrowth_material_scope(m.training_id); IF result IS NULL THEN RAISE EXCEPTION '유효한 다운로드 권한이 없습니다.' USING ERRCODE='42501'; END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.mygrowth_material_scope(uuid),public.mygrowth_material_list(uuid),public.mygrowth_material_reserve(uuid,text,bigint),public.mygrowth_material_issue(uuid),public.mygrowth_material_redeem(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.mygrowth_material_scope(uuid),public.mygrowth_material_list(uuid),public.mygrowth_material_reserve(uuid,text,bigint),public.mygrowth_material_issue(uuid),public.mygrowth_material_redeem(uuid) TO authenticated,service_role;
CREATE POLICY "My Growth materials are service transported only" ON storage.objects FOR ALL TO authenticated USING (bucket_id='mygrowth-materials' AND false) WITH CHECK (bucket_id='mygrowth-materials' AND false);
COMMENT ON TABLE public.mygrowth_materials IS 'Private permanently retained education files; no client grants; transport validates bytes and current scope; incomplete uploads not listed.';
COMMENT ON TABLE public.mygrowth_material_tickets IS 'Owner-bound seven-day authorization, not public storage signed URLs; every file request must revalidate current scope.';